From 2df3f53e085a2b0f288fab22a3c0279c61f4d30d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:20:25 +0100
Subject: [PATCH] components/batterycontrol: expose each battery's UPower path

The battery model gave no stable way to tell its batteries apart, so an
applet could not remember a chosen device. Add a Udi role with the UPower
object path, which the battery applet uses to show a chosen battery.

BUG: 526188
---
 components/batterycontrol/batterycontrol.cpp | 3 +++
 components/batterycontrol/batterycontrol.h   | 1 +
 2 files changed, 4 insertions(+)

diff --git a/components/batterycontrol/batterycontrol.cpp b/components/batterycontrol/batterycontrol.cpp
index 060d5895ac..6a1ae943b5 100644
--- a/components/batterycontrol/batterycontrol.cpp
+++ b/components/batterycontrol/batterycontrol.cpp
@@ -275,6 +275,8 @@ QVariant BatteryControlModel::data(const QModelIndex &index, int role) const
         return QVariant::fromValue(m_namesMonitor->updateBatteryName(*battery));
     case Type:
         return QVariant::fromValue(batteryTypeToString(battery));
+    case Udi:
+        return QVariant::fromValue(battery->udi());
     }
     return {};
 }
@@ -290,6 +292,7 @@ QHash<int, QByteArray> BatteryControlModel::roleNames() const
     roles[ChargeState] = QByteArrayLiteral("ChargeState");
     roles[PrettyName] = QByteArrayLiteral("PrettyName");
     roles[Type] = QByteArrayLiteral("Type");
+    roles[Udi] = QByteArrayLiteral("Udi");
     return roles;
 }

diff --git a/components/batterycontrol/batterycontrol.h b/components/batterycontrol/batterycontrol.h
index c847bd424f..c9a7cb0140 100644
--- a/components/batterycontrol/batterycontrol.h
+++ b/components/batterycontrol/batterycontrol.h
@@ -46,6 +46,7 @@ public:
         IsPowerSupply,
         ChargeState,
         Type,
+        Udi,
     };
     Q_ENUM(BatteryRoles)

-- 
2.53.0

From b981d5114e4d369c6f26914711e63a7dca02e492 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:20:25 +0100
Subject: [PATCH] applets/batterymonitor: allow choosing which battery the icon
 shows

The icon only showed the internal batteries, or the power mode on desktops
without one, so a mouse or gamepad level needed a click. A new Show on Icon
section in the context menu now lets the icon show one of those devices.

BUG: 526188
---
 .../batterymonitor/CompactRepresentation.qml  | 21 +++--
 applets/batterymonitor/main.qml               | 78 ++++++++++++++++++-
 applets/batterymonitor/main.xml               |  4 +
 3 files changed, 92 insertions(+), 11 deletions(-)

diff --git a/applets/batterymonitor/CompactRepresentation.qml b/applets/batterymonitor/CompactRepresentation.qml
index 0a02b660f..179279efb 100644
--- a/applets/batterymonitor/CompactRepresentation.qml
+++ b/applets/batterymonitor/CompactRepresentation.qml
@@ -27,6 +27,11 @@ MouseArea {
     property bool hasBatteries: false
     property bool hasInternalBatteries: false
     property bool hasCumulative: false
+    // Model data of the peripheral battery to show instead of the internal ones
+    property var iconBattery: null
+
+    readonly property int shownPercent: iconBattery ? iconBattery.Percent : batteryPercent
+    readonly property bool shownFullyCharged: iconBattery ? iconBattery.ChargeState === BatteryControlModel.FullyCharged : isSomehowFullyCharged

     required property bool isSomehowFullyCharged
     required property bool isDischarging
@@ -62,7 +67,7 @@ MouseArea {

         anchors.fill: parent

-        visible: root.isConstrained && (!root.hasInternalBatteries || (root.isManuallyInhibited && !root.isDischarging))
+        visible: root.isConstrained && ((!root.hasInternalBatteries && !root.iconBattery) || (root.isManuallyInhibited && !root.isDischarging))
         source: root.powerModeIconSrc
         active: root.containsMouse
     }
@@ -72,7 +77,7 @@ MouseArea {

         anchors.fill: parent

-        visible: root.isConstrained && !powerModeIcon.visible && root.hasInternalBatteries
+        visible: root.isConstrained && !powerModeIcon.visible && (root.hasInternalBatteries || root.iconBattery)

         // Show normal battery icon
         WorkspaceComponents.BatteryIcon {
@@ -81,10 +86,10 @@ MouseArea {
             anchors.fill: parent

             active: root.containsMouse
-            hasBattery: root.hasCumulative
-            percent: root.batteryPercent
-            isSomehowFullyCharged: root.isSomehowFullyCharged
-            pluggedIn: root.batteryPluggedIn
+            hasBattery: root.iconBattery ? root.iconBattery.PluggedIn && root.shownPercent >= 0 : root.hasCumulative
+            percent: Math.max(0, root.shownPercent)
+            isSomehowFullyCharged: root.shownFullyCharged
+            pluggedIn: root.iconBattery ? root.iconBattery.ChargeState === BatteryControlModel.Charging : root.batteryPluggedIn
             preferSymbolic: true
             powerProfileIconName: root.isInDefaultPowerProfile ? ""
                                 : root.isInPowersaveProfile    ? "powersave"
@@ -99,9 +104,9 @@ MouseArea {
             anchors.right: parent.right
             anchors.bottom: parent.bottom

-            visible: Plasmoid.configuration.showPercentage && root.batteryPercent >= 0 && !root.isSomehowFullyCharged
+            visible: Plasmoid.configuration.showPercentage && root.shownPercent >= 0 && !root.shownFullyCharged

-            text: i18nc("battery percentage below battery icon", "%1%", root.batteryPercent)
+            text: i18nc("battery percentage below battery icon", "%1%", root.shownPercent)

             // Non-default state to center if the badge is wider than the icon
             states: [
diff --git a/applets/batterymonitor/main.qml b/applets/batterymonitor/main.qml
index 7999bddb3..aeae1aecf 100644
--- a/applets/batterymonitor/main.qml
+++ b/applets/batterymonitor/main.qml
@@ -47,6 +47,56 @@ PlasmoidItem {
         id: inhibitionControl
     }

+    PlasmaCore.ActionGroup {
+        id: iconBatteryGroup
+    }
+
+    Instantiator {
+        id: iconBatteryActions
+
+        model: batteryControl
+        delegate: PlasmaCore.Action {
+            required property var model
+
+            text: model.PrettyName
+            visible: !model.IsPowerSupply
+            checkable: true
+            checked: Plasmoid.configuration.iconBattery === model.Udi
+            actionGroup: iconBatteryGroup
+            onTriggered: Plasmoid.configuration.iconBattery = model.Udi
+        }
+        onObjectAdded: (index, object) => {
+            Plasmoid.contextualActions.push(object);
+        }
+        onObjectRemoved: (index, object) => {
+            Plasmoid.contextualActions.splice(Plasmoid.contextualActions.indexOf(object), 1);
+        }
+    }
+
+    readonly property bool hasPeripheralBatteries: {
+        for (let i = 0; i < iconBatteryActions.count; ++i) {
+            if (iconBatteryActions.objectAt(i)?.visible) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    // The peripheral battery chosen to be shown on the icon, if it is connected
+    readonly property var iconBattery: {
+        const udi = Plasmoid.configuration.iconBattery;
+        if (!udi) {
+            return null;
+        }
+        for (let i = 0; i < iconBatteryActions.count; ++i) {
+            const action = iconBatteryActions.objectAt(i);
+            if (action?.visible && action.model.Udi === udi) {
+                return action.model;
+            }
+        }
+        return null;
+    }
+
     readonly property bool kcmAuthorized: KConfig.KAuthorized.authorizeControlModule("kcm_powerdevilprofilesconfig")
     readonly property bool kcmEnergyInformationAuthorized: KConfig.KAuthorized.authorizeControlModule("kcm_energyinfo")

@@ -100,7 +150,7 @@ PlasmoidItem {
     LayoutMirroring.childrenInherit: true

     Plasmoid.status: {
-        if (inhibitionControl.isManuallyInhibited || !powerProfilesControl.isInDefaultPowerProfile) {
+        if (iconBattery || inhibitionControl.isManuallyInhibited || !powerProfilesControl.isInDefaultPowerProfile) {
             return PlasmaCore.Types.ActiveStatus;
         }

@@ -112,6 +162,13 @@ PlasmoidItem {
     }

     toolTipMainText: {
+        if (iconBattery) {
+            if (iconBattery.Percent < 0) {
+                return iconBattery.PrettyName;
+            }
+            return i18nc("@info:tooltip %1 is a device name", "%1 at %2%", iconBattery.PrettyName, iconBattery.Percent);
+        }
+
         if (batteryControl.hasInternalBatteries && !batteryControl.hasCumulative) {
             return i18n("Battery is not present in the bay");
         }
@@ -144,13 +201,13 @@ PlasmoidItem {
         const parts = [];

         // Add special text for the "plugged in but still discharging" case
-        if (batteryControl.pluggedIn && batteryControl.state === BatteryControlModel.Discharging) {
+        if (!iconBattery && batteryControl.pluggedIn && batteryControl.state === BatteryControlModel.Discharging) {
             parts.push(i18n("The power supply is not powerful enough to charge the battery"));
         }

         if (!batteryControl.hasBatteries) {
             parts.push(i18n("No batteries available"));
-        } else if (batteryControl.hasInternalBatteries) {
+        } else if (!iconBattery && batteryControl.hasInternalBatteries) {
             if (batteryControl.remainingTime > 0) {
                 const remainingTimeString = KCoreAddons.Format.formatDuration(batteryControl.remainingTime, KCoreAddons.FormatTypes.HideSeconds);
                 if (batteryControl.state === BatteryControlModel.FullyCharged) {
@@ -218,6 +275,7 @@ PlasmoidItem {
         hasBatteries: batteryControl.hasBatteries
         hasInternalBatteries: batteryControl.hasInternalBatteries
         hasCumulative: batteryControl.hasCumulative
+        iconBattery: batterymonitor.iconBattery

         isSomehowFullyCharged: batteryControl.isSomehowFullyCharged
         isDischarging: !batteryControl.pluggedIn
@@ -319,6 +377,20 @@ PlasmoidItem {
             checkable: true
             checked: Plasmoid.configuration.showPercentage
             onTriggered: Plasmoid.configuration.showPercentage = checked;
+        },
+        PlasmaCore.Action {
+            isSeparator: true
+            text: i18nc("@title:menu section for choosing what the icon shows", "Show on Icon")
+            visible: batterymonitor.hasPeripheralBatteries
+        },
+        PlasmaCore.Action {
+            text: batteryControl.hasInternalBatteries ? i18nc("@action:inmenu show on icon", "Internal Battery")
+                                                      : i18nc("@action:inmenu show on icon", "Power Mode")
+            visible: batterymonitor.hasPeripheralBatteries
+            checkable: true
+            checked: !batterymonitor.iconBattery
+            actionGroup: iconBatteryGroup
+            onTriggered: Plasmoid.configuration.iconBattery = ""
         }
     ]

diff --git a/applets/batterymonitor/main.xml b/applets/batterymonitor/main.xml
index 31dff0878..d238ddd5b 100644
--- a/applets/batterymonitor/main.xml
+++ b/applets/batterymonitor/main.xml
@@ -10,6 +10,10 @@
       <label>If true, the battery will display a little charge percentage label inside.</label>
       <default>false</default>
     </entry>
+    <entry name="iconBattery" type="String">
+      <label>The UPower device whose battery is shown on the icon; if empty, the internal batteries are shown.</label>
+      <default></default>
+    </entry>
   </group>

 </kcfg>
-- 
2.53.0
